package com.example.hotspotshare;
import android.app.*;import android.os.*;import android.content.*;import android.net.*;import android.graphics.*;import android.widget.*;import java.io.*;import java.net.*;import java.util.*;import fi.iki.elonen.NanoHTTPD;import com.google.zxing.*;import com.google.zxing.common.BitMatrix;
public class MainActivity extends Activity{
 File dir; ShareServer server; TextView info; ImageView qr; int port=8765;
 public void onCreate(Bundle b){super.onCreate(b);dir=new File(getFilesDir(),"shared");dir.mkdirs();LinearLayout l=new LinearLayout(this);l.setPadding(24,24,24,24);l.setOrientation(1);info=new TextView(this);info.setTextSize(16);info.setText("Start sharing, then scan the QR code on a device connected to the same Wi-Fi/hotspot.");l.addView(info);Button start=new Button(this);start.setText("Start sharing + QR");l.addView(start);start.setOnClickListener(v->startServer());Button add=new Button(this);add.setText("Choose file to share");l.addView(add);add.setOnClickListener(v->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.setType("*/*");i.addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,7);});qr=new ImageView(this);l.addView(qr,new LinearLayout.LayoutParams(-1,650));TextView tip=new TextView(this);tip.setText("Local network only. Keep app open. Anyone on the same network with the URL can access shared files.");l.addView(tip);setContentView(l);}
 void startServer(){try{if(server!=null)server.stop();server=new ShareServer(port,dir);server.start(NanoHTTPD.SOCKET_READ_TIMEOUT,false);String ip=ip();String url="http://"+ip+":"+port+"/";info.setText("Sharing ON\\n"+url);BitMatrix m=new MultiFormatWriter().encode(url,BarcodeFormat.QR_CODE,500,500);Bitmap q=Bitmap.createBitmap(500,500,Bitmap.Config.RGB_565);for(int x=0;x<500;x++)for(int y=0;y<500;y++)q.setPixel(x,y,m.get(x,y)?Color.BLACK:Color.WHITE);qr.setImageBitmap(q);}catch(Exception e){info.setText("Server error: "+e.getMessage());}}
 String ip(){try{for(NetworkInterface n:Collections.list(NetworkInterface.getNetworkInterfaces()))for(InetAddress a:Collections.list(n.getInetAddresses()))if(!a.isLoopbackAddress()&&a instanceof Inet4Address&&a.isSiteLocalAddress())return a.getHostAddress();}catch(Exception e){}return "192.168.43.1";}
 protected void onActivityResult(int r,int c,Intent d){super.onActivityResult(r,c,d);if(r==7&&c==-1&&d!=null)try{Uri u=d.getData();String name="shared_"+System.currentTimeMillis();android.database.Cursor cur=getContentResolver().query(u,null,null,null,null);if(cur!=null){int ix=cur.getColumnIndex(android.provider.OpenableColumns.DISPLAY_NAME);if(cur.moveToFirst()&&ix>=0)name=cur.getString(ix);cur.close();}name=new File(name).getName().replaceAll("[^a-zA-Z0-9._ -]","_");try(InputStream in=getContentResolver().openInputStream(u);OutputStream out=new FileOutputStream(new File(dir,name))){byte[] z=new byte[8192];int n;while((n=in.read(z))>0)out.write(z,0,n);}Toast.makeText(this,"File added",0).show();if(server!=null)startServer();}catch(Exception e){Toast.makeText(this,e.toString(),1).show();}}
 protected void onDestroy(){if(server!=null)server.stop();super.onDestroy();}
 static class ShareServer extends NanoHTTPD{File dir;ShareServer(int p,File d){super(p);dir=d;}
 public Response serve(IHTTPSession s){String u=s.getUri();if(u.equals("/upload")&&s.getMethod()==Method.POST)try{Map<String,String> t=new HashMap<>();s.parseBody(t);String p=t.get("file");if(p==null)return newFixedLengthResponse(Response.Status.BAD_REQUEST,"text/plain","Missing file");String name=s.getParms().get("filename");if(name==null||name.isEmpty())name="upload_"+System.currentTimeMillis();name=new File(name).getName().replaceAll("[^a-zA-Z0-9._ -]","_");try(InputStream in=new FileInputStream(p);OutputStream out=new FileOutputStream(new File(dir,name))){byte[] b=new byte[8192];int n;while((n=in.read(b))>0)out.write(b,0,n);}return newFixedLengthResponse("<p>Upload complete. <a href='/'>Back</a></p>");}catch(Exception e){return newFixedLengthResponse(Response.Status.INTERNAL_ERROR,"text/plain",e.toString());}
 if(u.startsWith("/download/"))try{String n=URLDecoder.decode(u.substring(10),"UTF-8");File f=new File(dir,new File(n).getName());if(!f.isFile())return newFixedLengthResponse(Response.Status.NOT_FOUND,"text/plain","Not found");return newChunkedResponse(new FileInputStream(f),"application/octet-stream",f.length());}catch(Exception e){return newFixedLengthResponse(Response.Status.INTERNAL_ERROR,"text/plain","Read failed");}
 StringBuilder h=new StringBuilder("<meta name='viewport' content='width=device-width,initial-scale=1'><h1>Hotspot Share</h1><h2>Upload to phone</h2><form action='/upload' method='post' enctype='multipart/form-data'><input type='file' name='file'><button>Upload</button></form><h2>Download files</h2><ul>");File[] fs=dir.listFiles();if(fs!=null)for(File f:fs)if(f.isFile())try{h.append("<li>").append(f.getName().replace("&","&amp;").replace("<","&lt;")).append(" â <a href='/download/").append(URLEncoder.encode(f.getName(),"UTF-8")).append("'>Download</a></li>");}catch(Exception e){}h.append("</ul><p>Local network only. Anyone with access to this network can download these files.</p>");return newFixedLengthResponse(h.toString());}
 }
                                                                                                                                                                                                                                                                                                                                                                                                                                                          }
